CREATE TEMPORARY VIEW dwm_order_nmv_item_video_live_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_entrance
    ,is_ads
    ,card_type
    ,sort_type
    ,local_date
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv_usd
FROM
    order_nmv_raw_${grass_region_without_quote}
WHERE
    page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL
    AND card_type IN ('item', 'video', 'livestream')
GROUP BY
    1,2,3,4,5,6;

