CREATE TEMPORARY VIEW dws_order_nmv_${grass_region_without_quote} AS
SELECT
    local_date
    ,IF(search_entrance IS NOT NULL, search_entrance, '__ALL__') AS search_entrance
    ,IF(is_ads IS NOT NULL, is_ads, '__ALL__') AS is_ads
    ,IF(card_type IS NOT NULL, card_type, 'item+video+live') AS card_type
    ,IF(sort_type IS NOT NULL, sort_type, '__ALL__') AS sort_type
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv_usd) AS nmv_usd
    ,COUNT(DISTINCT IF(net_order_cnt > 0, user_id, NULL)) AS net_order_uu
FROM
    dwm_order_nmv_item_video_live_${grass_region_without_quote}
GROUP BY
    local_date
    ,CUBE(search_entrance, is_ads, card_type, sort_type)
UNION ALL
SELECT
    local_date
    ,IF(search_entrance IS NOT NULL, search_entrance, '__ALL__') AS search_entrance
    ,IF(is_ads IS NOT NULL, is_ads, '__ALL__') AS is_ads
    ,'__ALL__' AS card_type
    ,IF(sort_type IS NOT NULL, sort_type, '__ALL__') AS sort_type
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv_usd) AS nmv_usd
    ,COUNT(DISTINCT IF(net_order_cnt > 0, user_id, NULL)) AS net_order_uu
FROM
    dwm_order_nmv_all_${grass_region_without_quote}
GROUP BY
    local_date
    ,CUBE(search_entrance, is_ads, sort_type);

